def metric(data: pd.DataFrame) -> float:
    import numpy as np

    def ttb_choice(row):
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        for i in range(len(a)):
            if a[i] > b[i]:
                return 0
            elif b[i] > a[i]:
                return 1
        return 0.5

    ttb_preds = data.apply(ttb_choice, axis=1)
    match = (data['response'] == ttb_preds).mean()
    return float(match)

